      SUBROUTINE DSROTNCC     CALCULATES THE PARTIAL DERIVATIVES OF THE FIRST-ORDER MATRIXC     ELEMENTS OF THE SROT ELEMENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      REAL  DCS, DSN, DTHCC-----------------------------------------------------------------      DTH = DPARM*UNITI(13)      IF (TYPE .NE. 20 .AND. .NOT. BEFORE) DTH = - DTH      DCS = - SNR*DTH      IF (NDIF .LT. 0) DCS = - DCS      RV(1,1) = DCS      RV(2,2) = DCS      RV(3,3) = DCS      RV(4,4) = DCS      DSN = CSR*DTH      IF (NDIF .LT. 0) DSN = - DSN      RV(2,4) = DSN      RV(1,3) = DSN      RV(4,2) = - DSN      RV(3,1) = - DSN      RETURN      END